/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"launchkey-level-17","number":17,"title":"Included Software, Diagnostic Protocols & Studio Capstone","skillBand":"Textbook","duration":"From the course textbook","summary":"Registration of the Launchkey MK4 61 unlocks a software ecosystem comprising Novation Play (an instrument plugin developed with Klevgrand), Ableton Live 12 Lite, and an account-gated collection of third-party plugins, sample libraries, and ","modules":[{"id":"launchkey-m-17-1-1","code":"17.1","title":"Included Software, Diagnostic Protocols & Studio Capstone","blurb":"Registration of the Launchkey MK4 61 unlocks a software ecosystem comprising Novation Play (an instrument plugin developed with Klevgrand), Ableton Live 12 Lite, and an account-gated collection of third-party plugins, sample libraries, and ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-55","title":"Section overview","blocks":[{"type":"step","title":"Section 17.1 — Novation Play & Bundled Software Ecosystem","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Registration of the Launchkey MK4 61 unlocks a software ecosystem comprising <strong>Novation Play</strong> (an instrument plugin developed with Klevgrand), <strong>Ableton Live 12 Lite</strong>, and an account-gated collection of third-party plugins, sample libraries, and educational trials. This module covers software installation pipelines, licensing distinctions, and curricular boundaries."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Define the architectural role of <strong>Novation Play</strong> as a standalone and plugin virtual instrument.","Navigate the official software download and licensing pipeline via the Novation account portal.","Formulate the studio policy regarding Ableton Live 12 Lite versus Live Standard/Suite.","Identify dynamic, account-gated third-party software titles (Melodics, Klevgrand, GForce)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-1-1","title":"17.1.1: Novation Play Architecture","blocks":[{"type":"step","title":"17.1.1: Novation Play Architecture","blocks":[{"type":"prose","html":"Developed in partnership with Klevgrand, <strong>Novation Play</strong> is the flagship bundled sound generation instrument included with the Launchkey MK4:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                        NOVATION PLAY SOUND ENGINE                             |\n+-------------------+-----------------------------------------------------------+\n| Operational Form  | Runs as a **Standalone Application** (zero DAW required)  |\n|                   | or as a **VST3 / AU / AAX Plugin** inside any DAW         |\n+-------------------+-----------------------------------------------------------+\n| Preset Categories | Basses, Leads, Pads, Acoustic Pianos, Electric Keys, Kits |\n+-------------------+-----------------------------------------------------------+\n| Launchkey Mapping | Continuous encoders map directly to Play's macro controls |\n+-------------------+-----------------------------------------------------------+</pre>"},{"type":"prose","html":"<em>Identity Distinction</em>: Novation Play is software executed on the host CPU. The Launchkey hardware contains zero onboard sound engines."}]}],"minutes":8},{"id":"launchkey-l-17-1-2","title":"17.1.2: Software Download & License Management","blocks":[{"type":"step","title":"17.1.2: Software Download & License Management","blocks":[{"type":"prose","html":"To access bundled software:"},{"type":"list","items":["Navigate to <code>https://id.focusritegroup.com</code> and log in to the registered user account.","Access the <strong>My Software</strong> dashboard.","Download the native Windows (<code>.exe</code>) or macOS (<code>.dmg</code> / <code>.pkg</code>) installers.","Authorize software using the unique serial keys generated in the account dashboard."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-1-3","title":"17.1.3: Ableton Live Lite vs. Studio Standard Licensing","blocks":[{"type":"step","title":"17.1.3: Ableton Live Lite vs. Studio Standard Licensing","blocks":[{"type":"list","items":["<strong>Licensing Constraint</strong>: New Launchkey registrations provide an authorization code for <strong>Ableton Live 12 Lite</strong>.","<strong>Studio Policy</strong>: Because this academy standardizes on <strong>Ableton Live 12 Standard</strong>, students with existing Standard or Suite licenses must <strong>not</strong> downgrade or overwrite their installation with Live Lite. The <code>Launchkey MK4</code> hardware control script operates identically across all Live tiers."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-17-1-4","title":"17.1.4: Dynamic Account-Gated Additions & Melodics","blocks":[{"type":"step","title":"17.1.4: Dynamic Account-Gated Additions & Melodics","blocks":[{"type":"list","items":["<strong>Third-Party Additions</strong>: Soundpacks, sample bundles (e.g., Loopmasters collections), and plugin promotions vary dynamically based on the registration date.","<strong>Melodics Integration</strong>: Bundled subscriptions to the <strong>Melodics</strong> educational platform offer rhythm and pad training exercises; however, Melodics is an external practice utility and does not alter hardware controller behavior."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Novation Play identity (software plugin, not hardware sound); account download path; Live Lite vs Standard rule; dynamic account-gated bundle nature; Melodics role.","<strong>mustNotCover</strong>: Speculating that third-party bundle lists are permanently frozen into hardware specifications."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Open Novation Play (either standalone or as a plugin inside your DAW). Select an acoustic piano preset, verify that playing the Launchkey keybed triggers sound, and rotate Encoder 1 to confirm macro control."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Novation Play synthesizes audio cleanly through the computer audio interface.","Hardware keybed and encoders communicate seamlessly with the software."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-17-2-2","code":"17.2","title":"Included Software, Diagnostic Protocols & Studio Capstone","blurb":"This module establishes an exhaustive, systematic diagnostic protocol for resolving hardware communication faults, driver lockouts, channel routing errors, optical telemetry failures, and host integration breakdowns on Windows and macOS wor","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-56","title":"Section overview","blocks":[{"type":"step","title":"Section 17.2 — Systematic Hardware & Host Troubleshooting","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"This module establishes an exhaustive, systematic diagnostic protocol for resolving hardware communication faults, driver lockouts, channel routing errors, optical telemetry failures, and host integration breakdowns on Windows and macOS workstations."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the primary diagnostic workflow for \"No Sound\" symptoms.","Troubleshoot unlit DAW pads and failed control surface handshakes.","Diagnose and eliminate MIDI channel contention across Keys (Ch 1), Chords (Ch 3), and Drums (Ch 10).","Execute the official 5-step recovery procedure for Windows Red/Orange MIDI ports.","Remediate Windows Device Manager Error Code 10.","Resolve Novation Components connectivity failures (Red / Yellow status).","Recover from stuck Vegas Demonstration Mode and continuous C-1/C-2 note-off loops.","Apply the non-destructive troubleshooting hierarchy prior to executing a Factory Reset."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-2-1","title":"17.2.1: The \"No Audio Output\" Primary Diagnostic Protocol","blocks":[{"type":"step","title":"17.2.1: The \"No Audio Output\" Primary Diagnostic Protocol","blocks":[{"type":"prose","html":"When striking keys or pads produces no sound:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                  \"NO SOUND\" SYSTEMATIC FAULT TREE\n+-------------------------------------------------------------------------------+\n| 1. Physical Hardware &amp; MIDI Output Layer:                                     |\n|    - Is the OLED screen illuminated? (If off, exit Standby with [Shift]).     |\n|    - Does a software MIDI monitor register incoming Note On/Off packets?      |\n|                                                                               |\n| 2. DAW Track Routing Layer:                                                   |\n|    - Is an armed track listening to the correct MIDI Port (Interface 1)?      |\n|    - Is the track listening to the correct Channel?                           |\n|      (Keys: Ch 1 | Part B: Ch 2 | Chords: Ch 3 | Drums: Ch 10)                |\n|    - Is Track Monitoring set to \"Auto\" or \"In\"?                               |\n|                                                                               |\n| 3. Sound Synthesis &amp; Audio Engine Layer:                                      |\n|    - Is a virtual instrument instantiated on the track?                       |\n|    - Is the computer's Audio Device active in DAW Preferences (CoreAudio/ASIO)|\n|    - Are studio monitors / headphones powered and master volume unmuted?      |\n+-------------------------------------------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-17-2-2","title":"17.2.2: Unlit DAW Pads & Control Surface Handshake Breakdown","blocks":[{"type":"step","title":"17.2.2: Unlit DAW Pads & Control Surface Handshake Breakdown","blocks":[{"type":"prose","html":"If DAW pads and Shift-encoder modes remain completely dark when Live is open:"},{"type":"list","items":["<strong>Control Surface Name Check</strong>: Confirm the script is <code>Launchkey MK4</code> (not MK3 or Generic).","<strong>DAW Port Binding</strong>: Confirm Input/Output in the Control Surface row are set strictly to the <strong>DAW ports</strong> (<code>MIDIIN2</code> on Windows; <code>DAW In/Out</code> on Mac).","<strong>Firmware Update</strong>: Units running base factory firmware fail the Live 12 handshake; update firmware via Components."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-2-3","title":"17.2.3: Channel Mismatch Diagnostics (Chords & Drums)","blocks":[{"type":"step","title":"17.2.3: Channel Mismatch Diagnostics (Chords & Drums)","blocks":[{"type":"list","items":["<strong>Symptom</strong>: Keys play piano, but Chord Map pads produce zero sound.","<em>Cause</em>: Chord Map transmits on <strong>Channel 3</strong>. Track is locked strictly to Channel 1.","<em>Fix</em>: Set DAW track input to Channel 3 (or All Channels).","<strong>Symptom</strong>: Drum pads play piano notes instead of the Drum Rack.","<em>Cause</em>: Drum pads transmit on <strong>Channel 10</strong>. Track input is set to Channel 1.","<em>Fix</em>: Route the Drum Rack track to listen to Channel 10."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-17-2-4","title":"17.2.4: Windows Red / Orange MIDI Port Lockout Recovery","blocks":[{"type":"step","title":"17.2.4: Windows Red / Orange MIDI Port Lockout Recovery","blocks":[{"type":"prose","html":"If Ableton Live displays Red or Orange port buttons:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">OFFICIAL 5-STEP RECOVERY PROTOCOL:\n1. In Live Settings -&gt; Link, Tempo &amp; MIDI, toggle all Track/Sync/Remote buttons to OFF for the locked ports.\n2. In the Control Surface row, set Control Surface, Input, and Output dropdowns to \"None\".\n3. Close Ableton Live, all web browsers running Components, and background MIDI tools.\n4. Unplug the USB-C cable for 5 seconds, then plug directly into a motherboard USB port.\n5. Re-open Ableton Live. Re-select \"Launchkey MK4\" with DAW ports and re-enable the official 4-row matrix.</pre>"}]}],"minutes":8},{"id":"launchkey-l-17-2-5","title":"17.2.5: Windows Device Manager Error Code 10","blocks":[{"type":"step","title":"17.2.5: Windows Device Manager Error Code 10","blocks":[{"type":"prose","html":"If Windows Device Manager reports <code>Error Code 10: This device cannot start</code>:"},{"type":"list","items":["Disconnect passive, unpowered USB hubs; connect directly to a computer root port.","Replace USB-C cable.","In Device Manager, right-click <code>Launchkey MK4</code> -&gt; Uninstall device -&gt; Reinstall Novation USB driver -&gt; Reconnect hardware."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-2-6","title":"17.2.6: Novation Components Telemetry Failures","blocks":[{"type":"step","title":"17.2.6: Novation Components Telemetry Failures","blocks":[{"type":"list","items":["<strong>Status is RED</strong>: Browser lacks Web MIDI permission, or USB cable is disconnected. Use Google Chrome / Edge.","<strong>Status is YELLOW</strong>: Controller is stuck in Bootloader Mode. <strong>Press the physical [ PLAY ] button</strong> to launch the runtime firmware."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-17-2-7","title":"17.2.7: Special Fault Modes (Vegas Mode & Continuous Note-Offs)","blocks":[{"type":"step","title":"17.2.7: Special Fault Modes (Vegas Mode & Continuous Note-Offs)","blocks":[{"type":"list","items":["<strong>Stuck in Vegas Mode</strong>: If pads endlessly cycle rainbow colors, enter Settings -&gt; <code>Vegas Mode</code> -&gt; set to <strong>Off</strong>.","<strong>Continuous C-1 / C-2 Note-Off Messages</strong>: If a MIDI monitor displays continuous stream of C-1/C-2 messages, ensure the DAW control surface script is bound to Interface 2 (DAW port), not Interface 1 (MIDI port)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-2-8","title":"17.2.8: Factory Reset as the Absolute Last Resort","blocks":[{"type":"step","title":"17.2.8: Factory Reset as the Absolute Last Resort","blocks":[{"type":"prose","html":"A Factory Reset must only be executed if non-destructive troubleshooting fails:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------+\n|                  FACTORY RESET CONSEQUENCES (COMPONENTS)                |\n|                                                                         |\n|  Executing a Factory Reset in Novation Components:                      |\n|  1. Reverts all internal Settings (Channels, Velocity, Brightness)      |\n|     back to factory defaults.                                           |\n|  2. PERMANENTLY WIPES all user Custom Modes (Encoders, Pads, Faders).   |\n|  3. Re-enables Easy Start / Mass Storage Device (MSD) mode.             |\n|                                                                         |\n|  RULE OF DISCIPLINE: Exhaust systematic diagnostics before resetting!   |\n+-------------------------------------------------------------------------+</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: \"No sound\" 3-tier diagnostic tree; unlit DAW pad handshake recovery; Channel 1/3/10 mismatch fixes; Windows Red/Orange 5-step procedure; Windows Error Code 10; Components Red/Yellow recovery; Vegas mode recovery; Factory reset consequences.","<strong>mustNotCover</strong>: Speculation regarding unverified registry tweaks."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Build a 1-page quick-reference hardware fault card detailing the official primary check for: (1) No Sound, (2) Unlit DAW Pads, (3) Red/Orange Ports, (4) Yellow Components Status, and (5) Silent Chord Pads."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Fault card correctly matches all official Novation diagnostic procedures.","Factory reset is documented as the final fallback, not the initial step."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-17-3-3","code":"17.3","title":"Included Software, Diagnostic Protocols & Studio Capstone","blurb":"The Studio Capstone Project is the comprehensive practical examination for the Learning the Launchkey MK4 61 curriculum. To achieve graduation (Assessment Gate K), the student must document a complete hardware settings sheet, establish a ce","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-57","title":"Section overview","blocks":[{"type":"step","title":"Section 17.3 — Comprehensive Studio Capstone Project","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The Studio Capstone Project is the comprehensive practical examination for the <strong>Learning the Launchkey MK4 61</strong> curriculum. To achieve graduation (Assessment Gate K), the student must document a complete hardware settings sheet, establish a certified Ableton Live 12 Standard control surface integration, execute five distinct live musical performance exercises demonstrating mastery across all internal engines, and archive the project."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Document a complete, verified Hardware &amp; MIDI Configuration Sheet.","Establish and prove the certified Ableton Live 12 control surface integration.","Execute <strong>Performance Test A</strong>: Simultaneous Keybed (Part A) and Drum Pad (Channel 10) tracking.","Execute <strong>Performance Test B</strong>: Scale-quantized Chord Map progression with a latched, modified Arpeggiator pattern.","Execute <strong>Performance Test C</strong>: Multi-timbral Split or Layer performance across Channels 1 and 2.","Execute <strong>Performance Test D</strong>: Non-linear Session clip launching and hardware Step Sequencing.","Execute <strong>Performance Test E</strong>: Custom Mode macro automation via continuous encoders or linear faders.","Archive the completed studio production using Live's \"Collect All and Save\" protocol.","Complete Assessment Gate K."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-3-1","title":"17.3.1: The Hardware & MIDI Configuration Sheet","blocks":[{"type":"step","title":"17.3.1: The Hardware & MIDI Configuration Sheet","blocks":[{"type":"prose","html":"Before beginning the musical performance tests, document the active workstation environment:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                 STUDIO CAPSTONE HARDWARE CONFIGURATION SHEET                  |\n+-----------------------------------+-------------------------------------------+\n| Verification Item                 | Documented Workstation Value              |\n+-----------------------------------+-------------------------------------------+\n| **Host Operating System**         | Windows 10/11 (64-bit) OR Apple macOS     |\n| **Interface 1 Port String**       | Launchkey MK4 61 MIDI                     |\n| **Interface 2 Port String**       | MIDIIN2 (LKMK4 MIDI) / Launchkey DAW In   |\n| **Firmware Build Number**         | Verified via Novation Components Updates  |\n| **Keybed Part A MIDI Channel**    | **Channel 1**                             |\n| **Keybed Part B MIDI Channel**    | **Channel 2**                             |\n| **Chord Engines MIDI Channel**    | **Channel 3**                             |\n| **Drum Mode MIDI Channel**        | **Channel 10**                            |\n| **Default Split Point**           | **C3**                                    |\n| **Pad Aftertouch Setting**        | **Polyphonic**                            |\n| **Fader Pickup Setting**          | **Jump** (or Pickup)                      |\n+-----------------------------------+-------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-17-3-2","title":"17.3.2: Live 12 Control Surface Certification","blocks":[{"type":"step","title":"17.3.2: Live 12 Control Surface Certification","blocks":[{"type":"prose","html":"Verify in Ableton Live <code>Settings &gt; Link, Tempo &amp; MIDI</code>:"},{"type":"list","items":["<code>Control Surface: Launchkey MK4</code> is bound to the dedicated <strong>DAW ports</strong>.","All 4 rows of the Track/Sync/Remote matrix match the official table (Sync: ON for Output MIDI).","The <strong>2×8 Session focus ring</strong> is visibly active in Session View."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-17-3-3","title":"17.3.3: Performance Execution Requirements","blocks":[{"type":"step","title":"17.3.3: Performance Execution Requirements","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    THE 5 CAPSTONE PERFORMANCE CLAUSES                         |\n+-------------+-------------------------+---------------------------------------+\n| Clause      | Performance Title       | Required Hardware Execution           |\n+-------------+-------------------------+---------------------------------------+\n| **Test A**  | **Keys &amp; Drum Pads**    | Play a melodic synth from Part A keys |\n|             |                         | while finger-drumming on Drum pads    |\n|             |                         | (Channel 10) simultaneously.          |\n+-------------+-------------------------+---------------------------------------+\n| **Test B**  | **Scale, Chords &amp; Arp** | Set Scale to D Minor. Play a 4-chord  |\n|             |                         | progression from Chord Map (Ch 3).    |\n|             |                         | Latch an Arp pattern using a Tie or   |\n|             |                         | Accent modifier.                      |\n+-------------+-------------------------+---------------------------------------+\n| **Test C**  | **Split or Layer**      | Configure Split at C3. Play a bassline|\n|             |                         | in Part A (Ch 1) and a lead in Part B |\n|             |                         | (Ch 2) simultaneously.                |\n+-------------+-------------------------+---------------------------------------+\n| **Test D**  | **Session &amp; Sequencer** | Launch 2 clips and 1 scene from pads. |\n|             |                         | Enter Sequencer mode (`Shift+Pad 9`x2)|\n|             |                         | and step-sequence a 16-step beat.     |\n+-------------+-------------------------+---------------------------------------+\n| **Test E**  | **Custom Macro Mode**   | Switch Encoders or Faders to Custom 1.|\n|             |                         | Modulate at least 4 assigned macros   |\n|             |                         | on a focused software device.         |\n+-------------+-------------------------+---------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-17-3-4","title":"17.3.4: Project Archiving Protocol","blocks":[{"type":"step","title":"17.3.4: Project Archiving Protocol","blocks":[{"type":"prose","html":"Once all performance clauses are recorded into the DAW arrangement:"},{"type":"list","items":["In Ableton Live, navigate to <code>File &gt; Collect All and Save</code>.","Check all options (Files from Elsewhere, Files from Other Projects, Factory Packs) to consolidate all audio, MIDI, and instrument presets into a self-contained project folder.","Save the session as <code>Launchkey_MK4_61_Capstone_Graduation.als</code>."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Complete settings sheet; Live 12 surface certification; all 5 performance clauses (Keys+Drums, Scale+Chords+Arp, Split/Layer, Session+Sequencer, Custom Mode); Collect All and Save archiving.","<strong>mustNotCover</strong>: Requiring unowned third-party DAWs or hardware for graduation."],"ordered":false}]},{"type":"step","title":"Assessment Gate K (Comprehensive Hardware Graduation)","blocks":[{"type":"prose","html":"<strong>Objective</strong>: Final self-assessment confirming 100% operational and musical mastery of the Novation Launchkey MK4 61."},{"type":"prose","html":"<strong>Graduation Checklist</strong>:"},{"type":"list","items":["[ ] Hardware Configuration Sheet completed with exact system strings and firmware build.","[ ] Performance Test A recorded and verified across Channels 1 and 10.","[ ] Performance Test B recorded with D Minor scale-locked chords and latched arpeggio.","[ ] Performance Test C recorded demonstrating multi-timbral split performance.","[ ] Performance Test D recorded demonstrating Session clip launching and hardware step sequencing.","[ ] Performance Test E executed demonstrating Custom Mode continuous control.","[ ] Project collected, archived, and saved."],"ordered":true}]}],"minutes":8}],"exercises":[]}]};
